D.Quests[36075]={Title="力量的证明：独眼魔角",Objectives="把证明带到戈尔隆德的高山走廊，交给游侠乔纳。",Description="这只角证明了你有消灭独眼魔的能力，你的角斗士朋友目击了你的战斗！把这只角带回去给乔纳，换取你应得的嘉奖！"}
D.Quests[36076]={Title="力量的证明：独眼魔角",Objectives="把证明带到戈尔隆德的蛮兽岗哨，交给断肢。",Description="这支角证明了你有消灭独眼魔的能力，你的角斗士朋友可以作证！把这支角带回去给断肢，换取你应得的嘉奖！"}
D.Quests[36078]={Title="力量的证明：小戈隆鳞片",Objectives="把证明带到戈尔隆德的高山走廊，交给游侠乔纳。",Description="这块鳞片证明了你有消灭独眼魔的能力，你的角斗士朋友目击了你的战斗！把这块鳞片带回去给乔纳，换取你应得的嘉奖！"}
